using Confluent.Kafka;

var config = new ConsumerConfig
{
    BootstrapServers = "kafka:9092",
    GroupId = "analytics-job",
    AutoOffsetReset = AutoOffsetReset.Earliest
};

using var consumer = new ConsumerBuilder<Ignore, string>(config).Build();
consumer.Subscribe("clickstream");

while (true)
{
    var result = consumer.Consume();
    Console.WriteLine($"Event: {result.Message.Value} at offset {result.Offset}");
    // Multiple independent consumer groups can read the same topic
}

import { SQSClient, SendMessageCommand, ReceiveMessageCommand } from "@aws-sdk/client-sqs";

const sqs = new SQSClient({ region: "us-east-1" });

await sqs.send(new SendMessageCommand({
  QueueUrl: process.env.JOB_QUEUE_URL!,
  MessageBody: JSON.stringify({ type: "resize-image", url: "https://example.com/photo.jpg" }),
  DelaySeconds: 0,
  MessageAttributes: {
    priority: { DataType: "Number", StringValue: "1" }
  }
}));
